      // then darken to silhouettes against the last glow.
      let catchLight=smoothstep(-.36,-.06,height)*(1.-smoothstep(.10,.48,height));
      let near=valleySunFacing(ray,hour);
      let lightAzimuth=select(skyAzimuth(key.xz),valleySunAzimuth(hour),catchLight>.01);
      // Light comes from above and from the sun's side of the sky. Probing the
      // shape that way finds lit crowns where it thins and shaded bases where
      // it thickens.
      let sunward=dot(skyAzimuth(vec2f(ray.z,-ray.x)),lightAzimuth);
