      var dayLight=mix(vec3f(.36,.42,.56),vec3f(1.,1.,1.),day);
      var dayShade=mix(vec3f(.15,.19,.29),vec3f(.72,.80,.92),day);
      let warm=valleyTwilightColor(height+.08);
      let dim=mix(.55,1.,smoothstep(-.36,-.12,height));
