  let dx=vec2i(radius,0);let dy=vec2i(0,radius);
  let adjacent=vec4f(textureLoad(sceneDepth,clamp(pixel-dx,vec2i(0),limit),0),
                     textureLoad(sceneDepth,clamp(pixel+dx,vec2i(0),limit),0),
                     textureLoad(sceneDepth,clamp(pixel-dy,vec2i(0),limit),0),
                     textureLoad(sceneDepth,clamp(pixel+dy,vec2i(0),limit),0))*options.depthRange-z;
