  let tile=vec2i(cell.z%8,cell.z/8)*64;
  let pair=vec2i(round(textureLoad(townPalette,tile+cell.xy,0).rg*255.));
  let a=textureLoad(townPalette,vec2i(pair.x,512),0).rgb;
